{"untrustedEvidence":{"issue":{"number":7,"title":"Keep jobs with unassigned owner visible","state":"open","by":"sample-maintainer","labels":[],"body":"visibleJobs must retain every supplied job, including owner unassigned. For jobs alpha owned by Ada and beta owned by unassigned, the returned IDs must be alpha and beta, in that order.","comments":[]},"files":{"src/jobs.ts":"export type Job = { id: string; owner: string };
export function visibleJobs(jobs: Job[]): string[] {
  return jobs.filter(job => job.owner !== 'unassigned').map(job => job.id);
}
